  ('eating', 'ليرضى عن العبد أن يأكل الأكلة فيحمده عليها', '2026-08-21T13:00:00Z', $j$[{"id": "oOabSoIV", "text": "إنَّ اللهَ لَيَرضى عَنِ العَبدِ أن يَأكُلَ الأَكلةَ فيَحمَدَه عليها، أو يَشرَبَ الشَّربةَ فيَحمَدَه عليها.", "rawi": "أنس بن مالك", "book": "صحيح مسلم", "ref": "2734", "grade": "[صحيح]", "takhrij": "أخرجه الترمذي (1816)، وابن أبي شيبة (24499)، وابن منده في ((التوحيد)) (ص251) واللفظ لهم.", "categories": [{"id": "3d3d3e6201cb95c1ea4dfc77fedbd240", "name": "أدعية وأذكار - أذكار الطعام"}, {"id": "1942aff8a08f15f3acc923953dcb4fa3", "name": "أدعية وأذكار - حمد الله بعد الأكل والشرب"}, {"id": "3e4fcc70c32d80390a4706212ff4234a", "name": "أطعمة - ما يقول إذا فرغ من الطعام"}, {"id": "daa7903a59", "name": "آداب عامة - آداب الطعام"}, {"id": "8bfbf8d956", "name": "أدعية وأذكار - فضل التحميد والتسبيح والدعاء"}]}]$j$::jsonb,
