  ('exercise', 'المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف', '2026-08-21T13:00:00Z', $j$[{"id": "Ov16uqG0", "text": "المُؤمِنُ القَويُّ خَيرٌ وأحَبُّ إلى اللهِ مِنَ المُؤمِنِ الضَّعيفِ، وفي كُلٍّ خَيرٌ. احرِصْ على ما يَنفَعُكَ، واستَعِنْ باللهِ ولا تَعجِزْ، وإن أصابَكَ شَيءٌ فلا تَقُلْ: لو أنِّي فعَلتُ كان كَذا وكَذا، ولَكِن قُلْ: قدَرُ اللهِ وما شاءَ فعَلَ؛ فإنَّ (لو) تَفتَحُ عَمَلَ الشَّيطانِ.", "rawi": "أبو هريرة", "book": "صحيح مسلم", "ref": "2664", "grade": "[صحيح]", "takhrij": "أخرجه ابن ماجه (79)، وأحمد (8829)، وأبو يعلى (6251) جميعهم بلفظه.", "categories": [{"id": "6ff88be32e0f13cfd202f5c032a316a5", "name": "إيمان - فضل الإيمان"}, {"id": "6f4c1da6507c273b722b9b6da86f7871", "name": "توحيد - ما جاء في اللو"}, {"id": "800fbc4f137be512165ffb13a08b9346", "name": "رقائق وزهد - أي المؤمنين خير"}, {"id": "a1a6cc0f150cdc7da0070c79a011f497", "name": "قدر - الأمر بالعمل وترك العجز"}, {"id": "c131ad3b8a2f27cf5f63f911786266db", "name": "قدر - الرضا بالقضاء"}]}]$j$::jsonb,
   'Ov16uqG0', 'أخرجه ابن ماجه (79)، وأحمد (8829)، وأبو يعلى (6251) جميعهم بلفظه.', $j$[{"id": "6ff88be32e0f13cfd202f5c032a316a5", "name": "إيمان - فضل الإيمان"}, {"id": "6f4c1da6507c273b722b9b6da86f7871", "name": "توحيد - ما جاء في اللو"}, {"id": "800fbc4f137be512165ffb13a08b9346", "name": "رقائق وزهد - أي المؤمنين خير"}, {"id": "a1a6cc0f150cdc7da0070c79a011f497", "name": "قدر - الأمر بالعمل وترك العجز"}, {"id": "c131ad3b8a2f27cf5f63f911786266db", "name": "قدر - الرضا بالقضاء"}]$j$::jsonb),
  ('going-to-work', 'ما أكل أحد طعاما قط خيرا من أن يأكل من عمل يده', '2026-08-21T13:00:00Z', $j$[{"id": "ymcRhdPb", "text": "ما أكَلَ أحَدٌ طَعامًا قَطُّ خَيرًا مِن أن يَأكُلَ مِن عَمَلِ يَدِه، وإنَّ نَبيَّ اللهِ داوُدَ عليه السَّلامُ كان يَأكُلُ مِن عَمَلِ يَدِه.", "rawi": "المقدام بن معدي كرب", "book": "صحيح البخاري", "ref": "2072", "grade": "[صحيح]", "takhrij": "من أفراد البخاري على مسلم", "categories": [{"id": "75d058ec96950869518fea20949c0f55", "name": "إجارة - كسب الرجل وعمله بيده"}, {"id": "82ee55c0671ab5995ed8e2a3f9a1fed1", "name": "أنبياء - خصائص وفضائل"}, {"id": "e0a22d36e8e22f42fd09ff07775aa0cd", "name": "أنبياء - داود"}, {"id": "3ef1c2bc955f3fdb751925c8550ffd5b", "name": "رقائق وزهد - فضل العمل والتكسب"}, {"id": "8eb28af6f28bbf67866f539aa7319083", "name": "نفقة - أفضل الكسب"}]}]$j$::jsonb,
