  ('sleep', 'فإن لجسدك عليك حقا ولعينك عليك حقا', '2026-08-21T13:00:00Z', $j$[{"id": "FdijBGPM", "text": "يا عَبدَ اللهِ، ألَم أُخبَرْ أنَّك تَصومُ النَّهارَ وتَقومُ اللَّيلَ؟ قُلتُ: بَلى يا رَسولَ اللهِ، قال: فلا تَفعَلْ، صُمْ وأفطِرْ، وقُمْ ونَمْ؛ فإنَّ لجَسَدِك عليك حَقًّا، وإنَّ لعَينِك عليك حَقًّا، وإنَّ لزَوجِك عليك حَقًّا.", "rawi": "عبدالله بن عمرو", "book": "صحيح البخاري", "ref": "5199", "grade": "[صحيح]", "takhrij": "أخرجه البخاري (5199)، ومسلم (1159)", "categories": [{"id": "5fa4f564ef2abadb739e441129c57aa4", "name": "اعتصام بالسنة - ما يكره من التعمق والغلو والبدع"}, {"id": "0746b33219956b3c38198e1f4c7fb528", "name": "رقائق وزهد - الاجتهاد في العبادة"}, {"id": "79ebfc9e5a40c080ba07e5ba675ce75c", "name": "رقائق وزهد - القصد والمداومة على العمل"}, {"id": "7ecf234f3c46c9fc5ede2de38256868e", "name": "صيام - صيام الدهر"}, {"id": "5116e75fe6", "name": "صلاة - النهي عن التكلف والمشقة في العبادة"}]}]$j$::jsonb,
   'FdijBGPM', 'أخرجه البخاري (5199)، ومسلم (1159)', $j$[{"id": "5fa4f564ef2abadb739e441129c57aa4", "name": "اعتصام بالسنة - ما يكره من التعمق والغلو والبدع"}, {"id": "0746b33219956b3c38198e1f4c7fb528", "name": "رقائق وزهد - الاجتهاد في العبادة"}, {"id": "79ebfc9e5a40c080ba07e5ba675ce75c", "name": "رقائق وزهد - القصد والمداومة على العمل"}, {"id": "7ecf234f3c46c9fc5ede2de38256868e", "name": "صيام - صيام الدهر"}, {"id": "5116e75fe6", "name": "صلاة - النهي عن التكلف والمشقة في العبادة"}]$j$::jsonb),
  ('visiting-the-sick', 'من عاد مريضا لم يزل في خرفة الجنة', '2026-08-21T13:00:00Z', $j$[{"id": "C5JvShbV", "text": "مَن عادَ مَريضًا لَم يَزَلْ في خُرفةِ الجَنَّةِ، قيلَ: يا رَسولَ اللهِ، وما خُرفةُ الجَنَّةِ؟ قال: جَناها.", "rawi": "ثوبان مولى رسول الله صلى الله عليه وسلم", "book": "صحيح مسلم", "ref": "2568", "grade": "[صحيح]", "takhrij": "أخرجه أحمد (22389)، وأبو عوانة (11203) واللفظ لهما، والترمذي (967)، وابن حبان (598) باختلاف يسير.", "categories": [{"id": "1d2f286dc66a71cbf57be451d27330c1", "name": "جنة - صفة الجنة"}, {"id": "acc66ef56d", "name": "إيمان - الوعد"}, {"id": "00aaa0c86b", "name": "مريض - مشروعية عيادة المريض وفضلها"}]}]$j$::jsonb,
