  ('spending-on-family', 'دينار أنفقته في سبيل الله ودينار أنفقته في رقبة', '2026-08-21T13:00:00Z', $j$[{"id": "B7p5BSxU", "text": "دينارٌ أنفَقتَه في سَبيلِ اللهِ، ودينارٌ أنفَقتَه في رَقَبةٍ، ودينارٌ تَصَدَّقتَ به على مِسكينٍ، ودينارٌ أنفَقتَه على أهلِك؛ أعظَمُها أجرًا الذي أنفَقتَه على أهلِك.", "rawi": "أبو هريرة", "book": "صحيح مسلم", "ref": "995", "grade": "[صحيح]", "takhrij": "من أفراد مسلم على البخاري", "categories": [{"id": "573d479b139933cf75f7c7c036120105", "name": "صدقة - فضل الصدقة والحث عليها"}, {"id": "ac5638aa651ff995f011b25428f55b2e", "name": "نفقة - النفقة على الأهل"}, {"id": "a476ad69ea943e5b8512b5e2013725e7", "name": "نفقة - وجوب النفقة على الأهل والعيال"}, {"id": "68ae55d131", "name": "نفقة - الإنفاق في أوجه الخير وفضله"}, {"id": "1a6d256658", "name": "نفقة - نفقة الرقيق والرفق بهم والإحسان إليهم"}]}]$j$::jsonb,
